// Generic interface — reusable for any entity type
public interface IRepository<T> where T : class
{
    T GetById(int id);
    IEnumerable<T> GetAll();
    void Add(T entity);
    void Update(T entity);
    void Delete(int id);
}

// Concrete implementation
public class SqlRepository<T> : IRepository<T> where T : class
{
    private readonly DbContext _context;
    private readonly DbSet<T> _dbSet;

    public SqlRepository(DbContext context)
    {
        _context = context;
        _dbSet = context.Set<T>();
    }

    public T GetById(int id)
    {
        return _dbSet.Find(id) ?? throw new KeyNotFoundException();
    }

    public IEnumerable<T> GetAll()
    {
        return _dbSet.ToList();
    }

    public void Add(T entity)
    {
        _dbSet.Add(entity);
        _context.SaveChanges();
    }

    public void Update(T entity)
    {
        _dbSet.Update(entity);
        _context.SaveChanges();
    }

    public void Delete(int id)
    {
        var entity = GetById(id);
        _dbSet.Remove(entity);
        _context.SaveChanges();
    }
}

public interface IPrintable
{
    void Print();
    void PrintPreview();
}

public interface ISaveable
{
    void Save(string path);
    string Load(string path);
}

public interface ICloneable<T>
{
    T Clone();
}

// Implements ALL THREE interfaces
public class Document : IPrintable, ISaveable, ICloneable<Document>
{
    public string Title { get; set; }
    public string Content { get; set; }

    // IPrintable implementation
    public void Print()
    {
        Console.WriteLine($"Printing: {Title}");
        Console.WriteLine(Content);
    }

    public void PrintPreview()
    {
        Console.WriteLine($"[Preview] {Title}...");
    }

    // ISaveable implementation
    public void Save(string path)
    {
        File.WriteAllText(path, $"{Title}\n{Content}");
    }

    public string Load(string path)
    {
        return File.ReadAllText(path);
    }

    // ICloneable<Document> implementation
    public Document Clone()
    {
        return new Document { Title = Title, Content = Content };
    }
}

// Usage — polymorphic through any interface
IPrintable printable = new Document { Title = "Report", Content = "..." };
printable.Print();

ISaveable saveable = new Document { Title = "Report", Content = "..." };
saveable.Save("report.txt");

public interface INotificationService
{
    void Send(string message);

    // Default implementation — available to all implementors
    void SendWelcomeEmail(string userEmail)
    {
        string body = $"Welcome to our service, {userEmail}!";
        Send($"Email: {body}");
    }

    // Static members in interfaces (C# 11)
    static string ServiceName => "NotificationHub";
}

public class SmsNotificationService : INotificationService
{
    // Must implement the abstract method
    public void Send(string message)
    {
        Console.WriteLine($"SMS: {message}");
    }

    // Inherits SendWelcomeEmail() for free
    // But can override if needed
}

public class PushNotificationService : INotificationService
{
    public void Send(string message)
    {
        Console.WriteLine($"Push: {message}");
    }

    // Override the default implementation
    public void SendWelcomeEmail(string userEmail)
    {
        Send($"Welcome push notification for {userEmail}");
    }
}

// Usage
INotificationService service = new SmsNotificationService();
service.SendWelcomeEmail("alice@example.com"); // Uses the interface's default

// Interface — the contract
public interface IOrderService
{
    Task<Order> CreateAsync(OrderDto dto);
    Task<Order?> GetByIdAsync(int id);
}

// Implementation
public class OrderService : IOrderService
{
    private readonly IOrderRepository _repository;
    private readonly ILogger<OrderService> _logger;

    // Dependencies injected via constructor
    public OrderService(IOrderRepository repository, ILogger<OrderService> logger)
    {
        _repository = repository;
        _logger = logger;
    }

    public async Task<Order> CreateAsync(OrderDto dto)
    {
        _logger.LogInformation("Creating order for customer {CustomerId}", dto.CustomerId);
        var order = new Order(dto);
        await _repository.AddAsync(order);
        return order;
    }

    public async Task<Order?> GetByIdAsync(int id)
    {
        _logger.LogInformation("Fetching order {OrderId}", id);
        return await _repository.GetByIdAsync(id);
    }
}

// Test double — swaps real repository for a mock
public class FakeOrderRepository : IOrderRepository
{
    private readonly List<Order> _orders = new();

    public Task AddAsync(Order order)
    {
        _orders.Add(order);
        return Task.CompletedTask;
    }

    public Task<Order?> GetByIdAsync(int id)
    {
        return Task.FromResult(_orders.FirstOrDefault(o => o.Id == id));
    }
}
